<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Domain\Gateway;

use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentListItem;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentPurposeItem;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentRecord;

interface GdprConsentGateway
{
    /**
     * Returns purposes that still need a user decision for this tenant/user pair.
     *
     * @return GdprConsentPurposeItem[]
     */
    public function pendingPurposes(string $tenant, string $username): array;

    /**
     * Stores user decisions for GDPR purposes.
     *
     * @param array<string,bool> $decisions  Map of purposeKey => granted
     */
    public function storePurposeDecisions(
        string $tenant,
        string $username,
        array $decisions,
        string $ipAddress,
        string $userAgent
    ): void;

    /**
     * Lists all tenant GDPR purposes with the user's current decision status.
     *
     * @return GdprConsentListItem[]
     */
    public function listConsents(string $userUid, string $tenantUid): array;

    /**
     * Grants or revokes a single GDPR purpose for a user.
     */
    public function grantConsent(
        string $userUid,
        string $tenantUid,
        string $purposeKey,
        bool $granted,
        string $ipAddress,
        string $userAgent
    ): GdprConsentRecord;

    /**
     * Returns the full consent decision history for a user, newest first.
     *
     * @return GdprConsentRecord[]
     */
    public function historyConsents(string $userUid): array;
}
